package cn.xi.cloudwidget;
import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.time.*;

public class WaterChecks extends FeatureChecks {
    WaterAddActivity open(WaterHostActivity host,int index)throws Throwable{ActivityMonitor monitor=addMonitor(WaterAddActivity.class.getName(),null,false);main(()->host.actual.get(index).findViewById(R.id.hits).performClick());Activity activity=monitor.waitForActivityWithTimeout(6000);removeMonitor(monitor);check(activity instanceof WaterAddActivity,"whole water widget opens the lightweight record page "+index);WaterAddActivity sheet=(WaterAddActivity)activity;long end=SystemClock.uptimeMillis()+4000;while(sheet.amount==null&&SystemClock.uptimeMillis()<end){SystemClock.sleep(50);waitForIdleSync();}check(sheet.amount!=null,"record page is ready without opening the full editor "+index);return sheet;}
    void close(Activity activity)throws Throwable{main(activity::finish);waitForIdleSync();SystemClock.sleep(200);}
    void add(WaterHostActivity host,int ml)throws Throwable{WaterAddActivity sheet=open(host,0);main(()->{sheet.amount.setText(String.valueOf(ml));named(sheet.getWindow().getDecorView(),"添加").performClick();});waitForIdleSync();SystemClock.sleep(200);check(sheet.isFinishing(),"successful confirmed addition closes its record page "+ml);}
    void bitmaps(WaterHostActivity host)throws Throwable{for(int n=0;n<host.ids.size();n++){final int index=n;long deadline=SystemClock.uptimeMillis()+6000;boolean equal=false;while(SystemClock.uptimeMillis()<deadline){ImageView image=ready(host.actual.get(n));Bitmap nativeImage=((BitmapDrawable)image.getDrawable()).getBitmap();Card card=new Store(c).get(new Store(c).binding(host.ids.get(n)));card.shape=n==2?1:0;Bitmap expected=Renderer.render(c,card,nativeImage.getWidth(),nativeImage.getHeight(),false);equal=bitmapHash(expected).equals(bitmapHash(nativeImage));expected.recycle();if(equal)break;SystemClock.sleep(80);}check(equal,"native bitmap refreshes the correct card and shape "+index);float[] matrix=imageMatrix(ready(host.actual.get(n)));check(Math.abs(matrix[Matrix.MSCALE_X]-matrix[Matrix.MSCALE_Y])<.001,"water cup remains uniformly scaled in native host "+index);}}
    @Override public void onStart(){if(!"water".equals(args.getString("phase"))){super.onStart();return;}Bundle result=new Bundle();try{c=getTargetContext();Store store=new Store(c);LocalDate today=LocalDate.now();
        MainActivity home=(MainActivity)startActivitySync(new Intent(c,PortraitMainActivity.class).putExtra("page",0).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();View entry=find(home.getWindow().getDecorView(),"新建：今日喝水");check(entry!=null&&find(home.getWindow().getDecorView(),"新建：1×1 素材")!=null,"homepage exposes water while retaining the 1x1 material entry");ActivityMonitor editorMonitor=addMonitor(EditorActivity.class.getName(),null,false);main(entry::performClick);EditorActivity editor=(EditorActivity)editorMonitor.waitForActivityWithTimeout(5000);removeMonitor(editorMonitor);waitForIdleSync();Card draft=(Card)field("card").get(editor);final EditorActivity createdEditor=editor;check(draft.type==5&&draft.shape==0&&draft.waterGoalMl==2000&&draft.waterQuickMl==250&&draft.waterTotal(today)==0&&draft.stickers.length()==0,"new 2x2 water card defaults to 2000mL with no forced sticker or record");main(()->createdEditor.setShape(2));check(draft.shape==0,"water cannot become a 1x1 material widget");main(()->named(createdEditor.getWindow().getDecorView(),"自定义目标水量").performClick());AlertDialog dialog=(AlertDialog)field("waterNumberDialog").get(editor);EditText input=editText(dialog.getWindow().getDecorView());for(String invalid:new String[]{"","-1","10001","1.5","999999999999"}){main(()->{input.setText(invalid);dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});check(dialog.isShowing()&&draft.waterGoalMl==2000&&input.getError()!=null,"invalid custom daily goal is not written: "+invalid);}main(()->{input.setText("2500");dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});check(draft.waterGoalMl==2500,"native custom goal dialog accepts an integer in range");draft.id="qa034-created-water";main(editor::save);check(store.get(draft.id).waterGoalMl==2500,"water settings persist through actual editor Save");
        WaterHostActivity host=(WaterHostActivity)startActivitySync(new Intent(c,WaterHostActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();check(host.ids.size()==4,"native host binds three shared instances and one independent card");String otherBefore=store.get("qa034-water-independent").json().toString();
        for(int n=0;n<4;n++){WaterAddActivity sheet=open(host,n);check(store.get("qa034-water-linked").waterTotal(today)==0,"opening a water widget never records an implicit amount "+n);android.util.SizeF measured=WidgetGeometry.measured(c,host.ids.get(n),host.reported.get(n));check(measured!=null&&Math.abs(measured.getWidth()-host.actual.get(n).getWidth()/c.getResources().getDisplayMetrics().density)<.1,"water root click retains actual whole-widget geometry "+n);close(sheet);}
        WaterAddActivity first=open(host,0);main(()->named(first.getWindow().getDecorView(),"+250").performClick());check(store.get("qa034-water-linked").waterTotal(today)==0,"quick amount choice waits for explicit Add confirmation");close(first);
        for(int amount:new int[]{250,300,180})add(host,amount);check(store.get("qa034-water-linked").waterTotal(today)==730,"250 plus 300 plus 180 records exactly 730mL");bitmaps(host);check(store.get("qa034-water-independent").json().toString().equals(otherBefore),"another water card remains independent");
        WaterAddActivity undo=open(host,0);main(()->named(undo.getWindow().getDecorView(),"撤销最后一次记录").performClick());waitForIdleSync();check(store.get("qa034-water-linked").waterTotal(today)==550,"native undo removes only the last 180mL entry");
        WaterAddActivity invalid=open(host,0);String beforeInvalid=store.get("qa034-water-linked").waterHistory.toString();for(String bad:new String[]{"","0","-20","3001","1.5","99999999999999"}){main(()->{invalid.amount.setText(bad);invalid.submit();});check(store.get("qa034-water-linked").waterHistory.toString().equals(beforeInvalid)&&invalid.amount.getError()!=null,"invalid actual amount is rejected without history changes: "+bad);}close(invalid);
        editor=(EditorActivity)startActivitySync(new Intent(c,PortraitEditorActivity.class).putExtra("card","qa034-water-linked").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();EditorActivity goalEditor=editor;Card editing=(Card)field("card").get(editor);String history=store.get(editing.id).waterHistory.toString();main(()->named(goalEditor.getWindow().getDecorView(),"2500").performClick());main(goalEditor::save);check(store.get(editing.id).waterGoalMl==2500&&store.get(editing.id).waterHistory.toString().equals(history),"changing goal to 2500 preserves every recorded mL and timestamp");
        editor=(EditorActivity)startActivitySync(new Intent(c,PortraitEditorActivity.class).putExtra("card","qa034-water-linked").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Card staleDraft=(Card)field("card").get(editor);check(store.waterChange(staleDraft.id,today.toString(),250,false),"a second instance can record while the editor is open");EditorActivity staleEditor=editor;main(staleEditor::save);check(store.get(staleDraft.id).waterTotal(today)==800,"saving a stale style draft preserves the latest water history");
        add(host,3000);Card full=store.get("qa034-water-linked");check(full.waterTotal(today)==3800&&WaterDrawing.fraction(full,today)==1,"over-goal total stays real while cup fill clamps to 100 percent");String unchanged=full.waterHistory.toString();check(full.waterTotal(today.plusDays(1))==0&&!full.hasWater(today.plusDays(1))&&full.waterHistory.toString().equals(unchanged),"a new local day reads 0 without creating entries or deleting yesterday");check(!store.waterChange(full.id,today.toString(),250,false,today.plusDays(1),System.currentTimeMillis())&&store.get(full.id).waterHistory.toString().equals(unchanged),"day guard blocks a pre-midnight operation on the following day");
        ActivityMonitor oldMonitor=addMonitor(WaterAddActivity.class.getName(),null,false);PendingIntent old=WidgetProvider.waterForDay(c,host.ids.get(0),full.id,host.reported.get(0),today.minusDays(1));main(()->{try{old.send();}catch(Exception e){throw new RuntimeException(e);}});WaterAddActivity expired=(WaterAddActivity)oldMonitor.waitForActivityWithTimeout(5000);removeMonitor(oldMonitor);waitForIdleSync();check(expired!=null&&!expired.validDay()&&!named(expired.getWindow().getDecorView(),"添加").isEnabled(),"an actual stale-day PendingIntent opens a disabled record page");main(()->{expired.amount.setText("250");expired.submit();});check(store.get(full.id).waterHistory.toString().equals(unchanged),"stale-day activity cannot pollute today even when its submit method is called");close(expired);
        Card midnight=store.get(full.id);midnight.waterHistory=new org.json.JSONObject();midnight.addWater(600,today.minusDays(1),System.currentTimeMillis()-86400000L);store.save(midnight);main(()->new RefreshReceiver().onReceive(c,new Intent("cn.xi.cloudwidget.DAY")));check(store.get(full.id).waterTotal(today)==0&&store.get(full.id).waterTotal(today.minusDays(1))==600,"midnight refresh shows a new zero day and retains historical entries");bitmaps(host);
        Card decorated=store.get(full.id);decorated.addWater(750,today,System.currentTimeMillis());decorated.background=0xfff4e1e4;decorated.border=1;decorated.borderInk=Controls.BORDER_BLUE;decorated.addSticker("builtin:blue-sprig");decorated.stickers.getJSONObject(0).put("width",.14).put("x",.91).put("y",.90);store.save(decorated);WidgetProvider.updateCard(c,decorated.id);bitmaps(host);check(store.get(decorated.id).stickers.length()==1,"water supports existing backgrounds, borders and optional stickers");
        AppWidgetHost callbackHost=new AppWidgetHost(c,805);callbackHost.deleteHost();int widget=callbackHost.allocateAppWidgetId();check(AppWidgetManager.getInstance(c).bindAppWidgetIdIfAllowed(widget,new ComponentName(c,WideWidget.class)),"water pin callback test binds a real wide widget");new PinReceiver().onReceive(c,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widget).putExtra("card",decorated.id));check(store.binding(widget).equals(decorated.id),"adding the same saved water card links shared records instead of cloning history");callbackHost.deleteHost();main(host::refreshPreviews);
        result.putString("stream",report+"Checks passed this run: "+count+"\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable error){result.putString("stream",report+"FAIL "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
    static EditText editText(View root){if(root instanceof EditText)return (EditText)root;if(root instanceof ViewGroup)for(int n=0;n<((ViewGroup)root).getChildCount();n++){EditText result=editText(((ViewGroup)root).getChildAt(n));if(result!=null)return result;}return null;}
}
